describe('ChatOrchestrator tool input rejection', () => {
  it('resolves with the corrected retry after a schema rejection is shown to the provider', async () => {
    const registry = new ToolRegistry();
    const calls: Array<Record<string, unknown>> = [];
    registry.register(
      {
        name: 'lookup',
        description: 'looks things up',
        inputSchema: {type: 'object', properties: {q: {type: 'string'}}, required: ['q']},
      },
      async input => {
        calls.push(input);
        return 'found it';
      }
    );
    const seen: string[] = [];
    let round = 0;
    const provider: AIProvider = {
      async *sendMessage(params: SendMessageParams): AsyncGenerator<MessageChunk> {
        round += 1;
        seen.push(JSON.stringify(params.messages[params.messages.length - 1]));
        if (round === 1) yield {type: 'tool_use', toolCall: {id: 'c1', name: 'lookup', input: {}}};
        if (round === 2) yield {type: 'tool_use', toolCall: {id: 'c2', name: 'lookup', input: {q: 'x'}}};
        if (round <= 2) yield STOP_FOR_TOOL;
        else {
          yield {type: 'text', text: 'done'};
          yield STOP_DONE;
        }
      },
      async generateStructured<T>(): Promise<T> {
        return {} as T;
      },
    };
    const orchestrator = createChatOrchestrator(provider, promptBuilder, registry);

    const outcome = await outcomeOf(orchestrator.processMessage(createSession('ask')));

    expect({outcome, calls, rejectionShown: /required/.test(seen[1] ?? '') && /q/.test(seen[1] ?? '')}).toEqual({
      outcome: 'resolved without throwing',
      calls: [{q: 'x'}],
      rejectionShown: true,
    });
  });
});
EOF
